import { createContext, useContext, useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from './AuthContext';

const RealtimeContext = createContext(null);

export function RealtimeProvider({ children }) {
  const { user } = useAuth();
  const [tasks, setTasks] = useState([]);
  const [shopping, setShopping] = useState([]);

  useEffect(() => {
    if (!user?.householdId) return;

    console.log('[REALTIME] Starting subscriptions for household:', user.householdId);

    // ONE subscription for all tasks
    const tasksChannel = supabase
      .channel(`household-tasks-${user.householdId}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'tasks',
        filter: `household_id=eq.${user.householdId}`
      }, (payload) => {
        console.log('[REALTIME] Task change:', payload);
        // Update tasks state
      })
      .subscribe();

    // ONE subscription for all shopping
    const shoppingChannel = supabase
      .channel(`household-shopping-${user.householdId}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'shopping_items',
        filter: `household_id=eq.${user.householdId}`
      }, (payload) => {
        console.log('[REALTIME] Shopping change:', payload);
        // Update shopping state
      })
      .subscribe();

    // CRITICAL CLEANUP
    return () => {
      console.log('[REALTIME] Cleaning up subscriptions');
      supabase.removeChannel(tasksChannel);
      supabase.removeChannel(shoppingChannel);
    };
  }, [user?.householdId]);

  return (
    <RealtimeContext.Provider value={{ tasks, shopping }}>
      {children}
    </RealtimeContext.Provider>
  );
}

export const useRealtime = () => useContext(RealtimeContext);
