-- Enable realtime for the tables
ALTER PUBLICATION supabase_realtime ADD TABLE tasks;
ALTER PUBLICATION supabase_realtime ADD TABLE shopping_items;
ALTER PUBLICATION supabase_realtime ADD TABLE household_events;

-- Create trigger function for tasks
CREATE OR REPLACE FUNCTION broadcast_task_changes()
RETURNS TRIGGER AS $$
DECLARE
  event_name TEXT;
  household_topic TEXT;
BEGIN
  -- Determine event name based on operation
  IF TG_OP = 'INSERT' THEN
    event_name := 'task_created';
    household_topic := 'household:' || NEW.household_id::text || ':tasks';
  ELSIF TG_OP = 'UPDATE' THEN
    event_name := 'task_updated';
    household_topic := 'household:' || NEW.household_id::text || ':tasks';
  ELSIF TG_OP = 'DELETE' THEN
    event_name := 'task_deleted';
    household_topic := 'household:' || OLD.household_id::text || ':tasks';
  END IF;

  -- Broadcast the change
  PERFORM realtime.send(
    household_topic,
    event_name,
    jsonb_build_object(
      'id', COALESCE(NEW.id, OLD.id),
      'household_id', COALESCE(NEW.household_id, OLD.household_id),
      'operation', TG_OP
    ),
    false
  );

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

