-- Create a generic broadcast function for all tables
CREATE OR REPLACE FUNCTION broadcast_table_changes()
RETURNS TRIGGER AS $$
DECLARE
  topic_name TEXT;
  event_name TEXT;
  payload JSONB;
BEGIN
  -- Determine topic based on table and household_id
  IF TG_TABLE_NAME IN ('tasks', 'shopping_items', 'household_events', 'meals', 'polls') THEN
    topic_name := 'household:' || COALESCE(NEW.household_id, OLD.household_id)::text || ':' || TG_TABLE_NAME;
  ELSIF TG_TABLE_NAME = 'notifications' THEN
    topic_name := 'user:' || COALESCE(NEW.user_id, OLD.user_id)::text || ':notifications';
  ELSE
    topic_name := TG_TABLE_NAME || ':changes';
  END IF;

  -- Determine event name based on operation
  event_name := LOWER(TG_OP);

  -- Build payload
  IF TG_OP = 'DELETE' THEN
    payload := jsonb_build_object(
      'type', event_name,
      'table', TG_TABLE_NAME,
      'old', row_to_json(OLD)
    );
  ELSE
    payload := jsonb_build_object(
      'type', event_name,
      'table', TG_TABLE_NAME,
      'new', row_to_json(NEW),
      'old', CASE WHEN TG_OP = 'UPDATE' THEN row_to_json(OLD) ELSE NULL END
    );
  END IF;

  -- Broadcast the change
  PERFORM pg_notify(
    topic_name,
    payload::text
  );

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Drop existing triggers if they exist
DROP TRIGGER IF EXISTS tasks_broadcast_trigger ON tasks;
DROP TRIGGER IF EXISTS shopping_items_broadcast_trigger ON shopping_items;
DROP TRIGGER IF EXISTS household_events_broadcast_trigger ON household_events;
DROP TRIGGER IF EXISTS meals_broadcast_trigger ON meals;
DROP TRIGGER IF EXISTS polls_broadcast_trigger ON polls;
DROP TRIGGER IF EXISTS notifications_broadcast_trigger ON notifications;

-- Create triggers for all relevant tables
CREATE TRIGGER tasks_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON tasks
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

CREATE TRIGGER shopping_items_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON shopping_items
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

CREATE TRIGGER household_events_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON household_events
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

CREATE TRIGGER meals_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON meals
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

CREATE TRIGGER polls_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON polls
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

CREATE TRIGGER notifications_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON notifications
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

-- Add comment for documentation
COMMENT ON FUNCTION broadcast_table_changes() IS 'Broadcasts table changes via pg_notify for realtime subscriptions';

