-- =====================================================
-- MIGRATION: Fix Realtime Broadcast System
-- =====================================================
-- This migration fixes the delayed UI updates issue by:
-- 1. Replacing pg_notify with realtime.broadcast_changes
-- 2. Adding RLS policies for realtime.messages
-- 3. Ensuring proper broadcast configuration
-- =====================================================

-- Drop the old broadcast_table_changes function
DROP FUNCTION IF EXISTS broadcast_table_changes() CASCADE;

-- Create new broadcast function using realtime.broadcast_changes
CREATE OR REPLACE FUNCTION broadcast_table_changes()
RETURNS TRIGGER AS $$
DECLARE
  topic_name TEXT;
BEGIN
  -- Determine topic based on table and household_id
  -- Format: household:{household_id}:{table_name}
  IF TG_TABLE_NAME IN ('tasks', 'shopping_items', 'household_events', 'meals', 'polls') THEN
    topic_name := 'household:' || COALESCE(NEW.household_id, OLD.household_id)::text;
  ELSIF TG_TABLE_NAME = 'notifications' THEN
    topic_name := 'user:' || COALESCE(NEW.user_id, OLD.user_id)::text || ':notifications';
  ELSE
    topic_name := TG_TABLE_NAME || ':changes';
  END IF;

  -- Use realtime.broadcast_changes for proper Supabase Realtime integration
  PERFORM realtime.broadcast_changes(
    topic_name,           -- channel/topic name
    TG_OP,                -- event type (INSERT, UPDATE, DELETE)
    TG_OP,                -- event name
    TG_TABLE_NAME,        -- table name
    TG_TABLE_SCHEMA,      -- schema name
    NEW,                  -- new record
    OLD                   -- old record
  );

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Recreate triggers for all relevant tables
-- Tasks
DROP TRIGGER IF EXISTS tasks_broadcast_trigger ON tasks;
CREATE TRIGGER tasks_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON tasks
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

-- Shopping Items
DROP TRIGGER IF EXISTS shopping_items_broadcast_trigger ON shopping_items;
CREATE TRIGGER shopping_items_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON shopping_items
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

-- Household Events
DROP TRIGGER IF EXISTS household_events_broadcast_trigger ON household_events;
CREATE TRIGGER household_events_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON household_events
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

-- Meals
DROP TRIGGER IF EXISTS meals_broadcast_trigger ON meals;
CREATE TRIGGER meals_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON meals
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

-- Polls
DROP TRIGGER IF EXISTS polls_broadcast_trigger ON polls;
CREATE TRIGGER polls_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON polls
  FOR EACH ROW EXECUTE FUNCTION broadcast_table_changes();

-- =====================================================
-- RLS POLICIES FOR REALTIME.MESSAGES
-- =====================================================
-- These policies allow authenticated users to receive
-- broadcasts for their household data
-- =====================================================

-- Enable RLS on realtime.messages if not already enabled
ALTER TABLE realtime.messages ENABLE ROW LEVEL SECURITY;

-- Drop existing policies if they exist
DROP POLICY IF EXISTS "household_members_can_read_broadcasts" ON realtime.messages;
DROP POLICY IF EXISTS "household_members_can_send_broadcasts" ON realtime.messages;

-- Policy: Allow users to receive broadcasts for their household
CREATE POLICY "household_members_can_read_broadcasts" ON realtime.messages
FOR SELECT TO authenticated
USING (
  -- Allow if topic starts with 'household:' and user belongs to that household
  (
    topic LIKE 'household:%' AND
    EXISTS (
      SELECT 1 FROM users
      WHERE users.id = auth.uid()
      AND users.household_id::text = SPLIT_PART(topic, ':', 2)
    )
  )
  OR
  -- Allow if topic is for user's personal notifications
  (
    topic LIKE 'user:%:notifications' AND
    SPLIT_PART(topic, ':', 2)::uuid = auth.uid()
  )
);

-- Policy: Allow users to send broadcasts for their household
CREATE POLICY "household_members_can_send_broadcasts" ON realtime.messages
FOR INSERT TO authenticated
WITH CHECK (
  -- Allow if topic starts with 'household:' and user belongs to that household
  (
    topic LIKE 'household:%' AND
    EXISTS (
      SELECT 1 FROM users
      WHERE users.id = auth.uid()
      AND users.household_id::text = SPLIT_PART(topic, ':', 2)
    )
  )
  OR
  -- Allow if topic is for user's personal notifications
  (
    topic LIKE 'user:%:notifications' AND
    SPLIT_PART(topic, ':', 2)::uuid = auth.uid()
  )
);

-- Create index for better performance on household_id lookups
CREATE INDEX IF NOT EXISTS idx_users_household_id ON users(household_id);

-- =====================================================
-- VERIFICATION
-- =====================================================
-- Log successful migration
DO $$
BEGIN
  RAISE NOTICE 'Realtime broadcast system migration completed successfully';
  RAISE NOTICE 'Database triggers now use realtime.broadcast_changes()';
  RAISE NOTICE 'RLS policies configured for realtime.messages';
  RAISE NOTICE 'Client code should now use broadcast channels with private: true';
END $$;

